"use strict";(globalThis.webpackChunkgrc||=[]).push([[17282],{10480(e){e.exports=JSON.parse('[{"citeKey":"xu2026triggergated","slug":"xu-2026-trigger-gated-multimodal-1a84","title":"Trigger-Gated Multimodal LLM Agents for In-situ Scientific Simulation Monitoring","authors":["H. Xu","J. Cernuda","A. Kougkas","A. Gainaru","S. Klasky","X.-H. Sun","J. Lofstead"],"venue":"11th International Parallel Data Systems Workshop (PDSW 2026), held in conjunction with SC26","type":"WIP","entryType":"inproceedings","date":"November, 2026","year":2026,"era":"iit","month":11,"hasAbstract":false,"links":{"program":"https://sc26.conference-program.com/presentation/?id=ws_pdswwip113&sess=sess129"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"teves2026typesafe","slug":"teves-2026-type-safe-metadata-d6f0","title":"Type-Safe, Dynamically Defined Metadata Support for Scientific Applications","authors":["J. Teves","C. Brinker","A. Kougkas","A. Gainaru","S. Klasky","X.-H. Sun","J. Lofstead"],"venue":"11th International Parallel Data Systems Workshop (PDSW 2026), held in conjunction with SC26","type":"WIP","entryType":"inproceedings","date":"November, 2026","year":2026,"era":"iit","month":11,"hasAbstract":false,"links":{"program":"https://sc26.conference-program.com/presentation/?id=ws_pdswwip105&sess=sess129"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"rajesh2026explainability","slug":"rajesh-2026-io-observability-explainability-2bb9","title":"Extending I/O Observability to Explainability for Targeted Optimization","authors":["N. Rajesh","S. Neuwirth","J. Lofstead","A. Kougkas","X.-H. Sun","N. Dryden","H. Devarajan"],"venue":"International Conference for High Performance Computing, Networking, Storage, and Analysis (SC 2026)","type":"Poster","entryType":"misc","date":"November, 2026","year":2026,"era":"iit","month":11,"hasAbstract":false,"links":{"program":"https://sc26.conference-program.com/presentation/?id=rpost229&sess=sess313"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"devarajan2026datacrumbs","slug":"devarajan-2026-datacrumbs-11c5","title":"DataCrumbs: Efficient Cross-Layer Data Capture for Explainable I/O Performance in HPC Storage Stacks","authors":["H. Devarajan","S. Neuwirth","C. Wang","R. A. O. Sinurat","N. Rajesh","J. Lofstead","V. Sochat","D. Milroy","T. Scogland"],"venue":"8th Workshop on Programming and Performance Visualization Tools (ProTools 2026), held in conjunction with SC26","type":"Workshop","entryType":"inproceedings","date":"November, 2026","year":2026,"era":"iit","month":11,"hasAbstract":false,"links":{"program":"https://sc26.conference-program.com/presentation/?id=ws_prot105&sess=sess131"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"xu2026derivedquantity","slug":"xu-2026-rich-io-centric-derived-quantity-8c30","title":"Rich I/O-centric Derived Quantity Operators for Advanced In Situ Processing","authors":["H. Xu","J. Cernuda","A. Kougkas","X.-H. Sun","A. Gainaru","S. Klasky","M. Taufer","N. Tan","K. Assogba","M. Rafique","B. Nicolae","J. Teves","C. Brinker","L. Pouchard","J. Lofstead"],"venue":"22nd IEEE International Conference on eScience (eScience 2026)","type":"Conference","entryType":"inproceedings","date":"September, 2026","year":2026,"era":"iit","month":9,"abstract":"Scientific simulations produce increasingly large datasets that surpass practical limits for frequent input and output operations. Although performing analysis directly as data is produced (in situ) can mitigate this problem, embedding such analysis routines into complex scientific codes is often impractical or inflexible. We address this by introducing derived quantity operators that provide a modular and pluggable framework within high-level I/O libraries, enabling sophisticated in situ analysis to be performed transparently during data output with minimal modifications to the host application. The operators bind to persistent hierarchical storage through operator-declared metadata, allowing cross-timestep and cross-run analysis to be carried out seamlessly within the I/O path. We demonstrate the capabilities of our operators by integrating correctness validation and important scientific metrics, traditionally executed after simulation runs, directly into the I/O pathway as derived quantities. Our implementation illustrates how complex, non-mathematical analyses such as runtime validation can be efficiently performed during simulation, enabling early detection of errors. Our work broadens the range of in situ analyses achievable through derived quantity operators, promoting more flexible, intelligent, and reliable scientific workflows.","hasAbstract":true,"lede":"Scientific simulations produce increasingly large datasets that surpass practical limits for frequent input and output operations.","links":{"pdf":"https://grc.iit.edu/papers/2026/xu-2026-rich-io-centric-derived-quantity-8c30.pdf"},"tags":["IOWarp","Coeus"],"_projectIds":["iowarp","coeus"],"_funding":[{"agency":"DOE","award":"DE-SC0023263","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"gainaru2024deriveor","slug":"gainaru-2024-derive-or-4aad","title":"To Derive or Not to Derive: I/O Libraries Take Charge of Derived Quantities Computation","authors":["A. Gainaru","G. Eisenhauer","N. Podhorszki","L. Dulac","Q. Gong","A. Kougkas","J. Lofstead","X.-H. Sun","S. Klasky"],"venue":"IEEE/SBC 36th International Symposium on Computer Architecture and High Performance Computing (SBAC-PAD 2024), Hawaii, USA","type":"Conference","entryType":"inproceedings","date":"November, 2024","year":2024,"era":"iit","month":11,"doi":"10.1109/sbac-pad63648.2024.00030","abstract":"The ever-increasing volume of data produced by HPC simulations necessitates scalable methods for data explo- ration and knowledge extraction. Scientific data analysis often in- volves complex queries across distributed datasets, requiring ma- nipulation of multiple primary variables and generating derived data that needs to be handled efficiently, creating challenges for applications that need to parse many large datasets. Relying on individual applications to handle all intermediate data generally leads to redundant computations across studies and unnecessary data transfers. In this paper, we investigate the performance of different approaches where applications define derived variables as quantities of interest (QoIs) and offload the computation and transfer of these QoIs to the I/O library. This significantly reduces redundancy and optimizes data movement across the distributed storage and processing infrastructure by allowing control over when and where derived variables are computed. We present a detailed analysis of the performance-storage trade-offs associated with different solutions and showcase results for our study on two large-scale datasets created from climate and combustion simulations.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2024/gainaru-2024-derive-or-4aad.pdf"},"tags":["HPC Analysis","Large-Scale I/O","Derived Variables","Quantities of Interest"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"logan2024evaluationdaos","slug":"logan-2024-evaluation-daos-6eb2","title":"An Evaluation of DAOS for Simulation and Deep Learning HPC Workloads","authors":["L. Logan","J. Lofstead","A. Kougkas","X.-H. Sun"],"venue":"SIGOPS Operating Systems Review (OSR\'24)","type":"Journal","entryType":"article","date":"June, 2024","year":2024,"era":"iit","month":6,"doi":"10.1145/3689051.3689058","abstract":"Traditionally, distributed storage systems have relied upon the interfaces provided by OS kernels to interact with stor- age hardware. However, much research has shown that OSes impose serious overheads on every I/O operation, especially on high-performance storage and networking hardware (e.g., PMEM and 200GBe). Thus, distributed storage stacks are being re-designed to take advantage of this modern hard- ware by utilizing new hardware interfaces which bypass the kernel entirely. However, the impact of these optimizations have not been well-studied for real HPC workloads on real hardware. In this work, we provide a comprehensive evalua- tion of DAOS: a state-of-the-art distributed storage system which re-architects the storage stack from scratch for mod- ern hardware. We compare DAOS against traditional storage stacks and demonstrate that by utilizing optimal interfaces to hardware, performance improvements of up to 6x can be observed in real scientific applications.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2024/logan-2024-evaluation-daos-6eb2.pdf"},"tags":["Distributed Computing","Distributed Storage","Flash Memory","Machine Learning","Parallel Computing","Phase Change Memory"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"cernuda2024hades","slug":"cernuda-2024-hades-e18c","title":"Hades: A Context-Aware Active Storage Framework for Accelerating Large-Scale Data Analysis","authors":["J. Cernuda","L. Logan","A. Gainaru","J. Lofstead","A. Kougkas","X.-H. Sun"],"venue":"The 24th IEEE/ACM international Symposium on Cluster, Cloud and Internet Computing (CCGRID 2024)","type":"Conference","entryType":"inproceedings","date":"May, 2024","year":2024,"era":"iit","month":5,"doi":"10.1109/ccgrid59990.2024.00070","abstract":"Modern simulation workflows generate and analyze massive amounts of data using I/O libraries like Adios2 and NetCDF. Although extensive work has optimized the I/O processes during the simulation phase, executing analytical queries-which often require iterative traversals of large files for insights-is cumbersome and usually constrained by low I/O performance. Instead of waiting for the analysis phase to process queries, quantities can be derived asynchronously during data production and cached, speeding up future queries. In this work, we introduce a context-aware I/O layer named \'Hades.\' It is designed to efficiently derive insights from selected quantities without compromising overall workflow performance. Hades actively and asynchronously computes and stores these quantities while the data is in transit. Hades leverages a hierarchical buffering system with data access-aware prefetching to ensure quick and timely access to relevant data. It offers a flexible query interface empowering users to easily define derived quantities and provide control over data placement decisions. Hades is implemented using an Adios2 plugin engine and the Hermes buffering platform, enabling transparent use by any Adios-powered application or workflow. Experimental results demonstrate performance improvements by up to 3-4x for tested real-world scientific producer-consumer workflows. Index Terms-Active Storage, Hierarchical Storage, Context Awareness, Metadata Management, Data Operator, In-transit Computing","hasAbstract":true,"lede":"We introduce a context-aware I/O layer named \'Hades.\'","links":{"pdf":"https://grc.iit.edu/papers/2024/cernuda-2024-hades-e18c.pdf"},"tags":["Active Storage","Hierarchical Storage","Context Awareness","Metadata Management","Data Operator","In-Transit Computing","Coeus"],"_projectIds":["coeus"],"_funding":[{"agency":"DOE","award":"DE-SC0023263","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"logan2023evaluationdaos","slug":"logan-2023-evaluation-daos-a960","title":"An Evaluation of DAOS for Simulation and Deep Learning HPC Workloads","authors":["L. Logan","J. Lofstead","A. Kougkas","X.-H. Sun"],"venue":"The 3rd Workshop on Challenges and Opportunities of Efficient and Performant Storage Systems (CHEOPS\'23)","type":"Workshop","entryType":"inproceedings","date":"May, 2023","year":2023,"era":"iit","month":5,"doi":"10.1145/3578353.3589542","abstract":"Traditionally, distributed storage systems have relied upon the interfaces provided by OS kernels to interact with stor- age hardware. However, much research has shown that OSes impose serious overheads on every I/O operation, especially on high-performance storage and networking hardware (e.g., PMEM and 200GBe). Thus, distributed storage stacks are being re-designed to take advantage of this modern hard- ware by utilizing new hardware interfaces which bypass the kernel entirely. However, the impact of these optimizations have not been well-studied for real HPC workloads on real hardware. In this work, we provide a comprehensive evalua- tion of DAOS: a state-of-the-art distributed storage system which re-architects the storage stack from scratch for mod- ern hardware. We compare DAOS against traditional storage stacks and demonstrate that by utilizing optimal interfaces to hardware, performance improvements of up to 6x can be observed in real scientific applications.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2023/logan-2023-evaluation-daos-a960.pdf"},"tags":["Distributed Computing","Distributed Storage","Flash Memory","Machine Learning","Parallel Computing","Phase Change Memory"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"logan2022labstor","slug":"logan-2022-labstor-f69d","title":"LabStor: A Modular and Extensible Platform for Developing High-Performance, Customized I/O Stacks in Userspace","authors":["L. Logan","J. Cernuda","J. Lofstead","X.-H. Sun","A. Kougkas"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'22)","type":"Conference","entryType":"inproceedings","date":"November, 2022","year":2022,"era":"iit","month":11,"doi":"10.1109/sc41404.2022.00028","abstract":"Traditionally, I/O systems have been developed within the confines of a centralized OS kernel. This led to monolithic and rigid storage systems that are limited by low development speed, expressiveness, and performance. Various assumptions are imposed including reliance on the UNIX-file abstraction, the POSIX standard, and a narrow set of I/O policies. However, this monolithic design philosophy makes it difficult to develop and deploy new I/O approaches to satisfy the rapidly-evolving I/O requirements of modern scientific applications. To this end, we propose LabStor: a modular and extensible platform for developing high-performance, customized I/O stacks. Single-purpose I/O modules (e.g, I/O schedulers) can be developed in the comfort of userspace and released as plug-ins, while end-users can compose these modules to form workload- and hardware-specific I/O stacks. Evaluations show that by switching to a fully modular design, tailored I/O stacks can yield performance improvements of up to 60% in various applications.","hasAbstract":true,"lede":"To this end, we propose LabStor: a modular and extensible platform for developing high-performance, customized I/O stacks.","links":{"pdf":"https://grc.iit.edu/papers/2022/logan-2022-labstor-f69d.pdf","slides":"https://grc.iit.edu/papers/2022/logan-2022-labstor-f69d-slides.pdf"},"tags":["Clouds and Distributed Computing","Programming Frameworks","System Software","ChronoLog"],"_projectIds":["chronolog"],"_funding":[{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"NSF","award":"OAC-2104013","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"logan2021utilizingpersistent","slug":"logan-2021-utilizing-persistent-24d5","title":"Utilizing Persistent Memory in Parallel I/O Libraries","authors":["L. Logan","J. Lofstead","S. Levy","P. Widener","X.-H. Sun","A. Kougkas"],"venue":"The 2021 International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'21), November 14\u201319, 2021","type":"Poster","entryType":"misc","date":"November, 2021","year":2021,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2021/logan-2021-utilizing-persistent-24d5.pdf","poster":"https://grc.iit.edu/papers/2021/logan-2021-utilizing-persistent-24d5-poster.pdf"},"tags":["Persistent Memory","Libraries","Memory Management","Memory Mapped I/O"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"logan2021pmemcpy","slug":"logan-2021-pmemcpy-f81c","title":"pMEMCPY: a simple, lightweight, and portable I/O library for storing data in persistent memory","authors":["L. Logan","J. Lofstead","S. Levy","P. Widener","X.-H. Sun","A. Kougkas"],"venue":"The 1st Workshop on Re-envisioning Extreme-Scale I/O for Emerging Hybrid HPC Workloads (REX-IO\'21), in conjunction with the 2021 IEEE International Conference on Cluster Computing (CLUSTER\'21), September 7-10, 2021","type":"Workshop","entryType":"inproceedings","date":"September, 2021","year":2021,"era":"iit","month":9,"doi":"10.1109/cluster48925.2021.00098","abstract":"Persistent memory (PMEM) devices can achieve comparable performance to DRAM while providing significantly more capacity. This has made the technology compelling as an expansion to main memory. Rethinking PMEM as storage devices can offer a high performance buffering layer for HPC applications to temporarily, but safely store data. However, modern parallel I/O libraries, such as HDF5 and pNetCDF, are complicated and introduce significant software and metadata overheads when persisting data to these storage devices, wasting much of their potential. In this work, we explore the potential of PMEM as storage through pMEMCPY: a simple, lightweight, and portable I/O library for storing data in persistent memory. We demonstrate that our approach is up to 2x faster than other popular parallel I/O libraries under real workloads.","hasAbstract":true,"lede":"We explore the potential of PMEM as storage through pMEMCPY: a simple, lightweight, and portable I/O library for storing data in persistent memory.","links":{"pdf":"https://grc.iit.edu/papers/2021/logan-2021-pmemcpy-f81c.pdf"},"tags":["Persistent Memory","Libraries","Memory Management","Memory Mapped I/O"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2019labios","slug":"kougkas-2019-labios-8411","title":"LABIOS: A Distributed Label-Based I/O System","authors":["A. Kougkas","H. Devarajan","J. Lofstead","X.-H. Sun"],"venue":"The 28th International Symposium on High-Performance Parallel and Distributed Computing (HPDC\'19), Phoenix, USA 2019. pp. 13-24. Karsten Schwan Best Paper Award","type":"Conference","entryType":"inproceedings","date":"June, 2019","year":2019,"era":"iit","month":6,"doi":"10.1145/3307681.3325405","abstract":"In the era of data-intensive computing, large-scale applications, in both scientific and the BigData communities, demonstrate unique I/O requirements leading to a proliferation of different storage devices and software stacks, many of which have conflicting re- quirements. In this paper, we investigate how to support a wide variety of conflicting I/O workloads under a single storage system. We introduce the idea of a Label, a new data representation, and, we present LABIOS: a new, distributed, Label- based I/O system. LABIOS boosts I/O performance by up to 17x via asynchronous I/O, supports heterogeneous storage resources, offers storage elastic- ity, and promotes in-situ analytics via data provisioning. LABIOS demonstrates the effectiveness of storage bridging to support the convergence of HPC and BigData workloads on a single platform.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2019/kougkas-2019-labios-8411.pdf","slides":"https://grc.iit.edu/papers/2019/kougkas-2019-labios-8411-slides.pdf"},"tags":["Label-Based I/O","Storage Bridging","Heterogeneous I/O","Datalabels","Task-Based I/O","Exascale I/O","Energy-Aware I/O","Elastic Storage","Hermes"],"_projectIds":["hermes","labios"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"NSF","award":"CCF-1744317","agencyKnown":true},{"agency":"NSF","award":"CNS-1730488","agencyKnown":true},{"agency":"NSF","award":"CNS-1526887","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"grcAwards":"Karsten Schwan Best Paper Award","status":"published","visibility":"public"},{"citeKey":"kougkas2018harmonia","slug":"kougkas-2018-harmonia-5ca9","title":"Harmonia: An Interference-Aware Dynamic I/O Scheduler for Shared Non-Volatile Burst Buffers","authors":["A. Kougkas","H. Devarajan","X.-H. Sun","J. Lofstead"],"venue":"The IEEE International Conference on Cluster Computing 2018 (Cluster\'18), Belfast, UK2018. pp. 290-301.","type":"Conference","entryType":"inproceedings","date":"September, 2018","year":2018,"era":"iit","month":9,"doi":"10.1109/cluster.2018.00046","abstract":"Modern HPC systems employ burst buffer installations to reduce the peak I/O requirements for external storage and deal with the burstiness of I/O in modern scientific applications. These I/O buffering resources are shared between multiple applications that run concurrently. This leads to severe performance degradation due to contention, a phenomenon called cross-application I/O interference. In this paper, we first explore the negative effects of interference at the burst buffer layer and we present two new metrics that can quantitatively describe the slowdown applications experience due to interference. We introduce Harmonia, a new dynamic I/O scheduler that is aware of interference, adapts to the underlying system, implements a new 2-way decision-making process and employs several scheduling policies to maximize the system efficiency and applications\' performance. Our evaluation shows that Harmonia, through better I/O scheduling, can outperform by 3x existing state-of-the-art buffering management solutions and can lead to better resource utilization.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2018/kougkas-2018-harmonia-5ca9.pdf","slides":"https://grc.iit.edu/papers/2018/kougkas-2018-harmonia-5ca9-slides.pdf"},"tags":["Hermes"],"_projectIds":["hermes"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"}]')}}]);